{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Compound 33, a heteroaromatic morpholine analogue, achieved a brain/plasma Kp of 11.4 in mice with negligible P-gp efflux, directly supporting CNS access for the morpholino-heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "18F-JNJ-64413739, a CF3-pyridine heteroaromatic radiotracer, showed high brain uptake and fast kinetics in rodents and non-human primates, supporting BBB penetration of the CF3-heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PET imaging in rats showed that [11C]13, a CF3-substituted heteroaromatic with a saturated N-ring, accumulated in brain, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084, a morpholine-containing compound, rapidly distributed to mouse brain with brain concentrations exceeding plasma at Tmax, supporting CNS distribution of morpholine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Flucytosine, an amino-substituted heteroaromatic, achieved ~75% CSF/serum in humans, supporting that polar aminoheteroaromatic molecules can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A CF3-heteroaryl carboxylic acid crossed the rat BBB by dynamic PET, albeit at low uptake, confirming that CF3-heteroaromatic motifs can enter brain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A CF3-substituted benzamide showed 1.07% dose/organ rat brain uptake at 2 min, supporting CNS penetration for CF3-containing aromatic compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple structurally relevant CNS-penetrant analogues (morpholino-heteroaromatic, CF3-pyridine, aminoheteroaromatic) support meaningful brain access for the query; no contradictory evidence.",
  "evidence_gaps": [
    "No direct brain or CSF PK measurement for the exact query molecule.",
    "Efflux liability of the query was not directly measured, though a close morpholino-heteroaromatic analogue showed negligible P-gp efflux.",
    "Human CNS exposure data for the exact query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

